RpkiSignedMessage-2025 { iso(1) member-body(2) us(840) rsadsi(113549) pkcs(1) pkcs9(9) smime(16) mod(0) id-mod-rpkiSignedMessage-2025(TBD) }
DEFINITIONS EXPLICIT TAGS ::= BEGIN
IMPORTS CONTENT-TYPE, Digest, DigestAlgorithmIdentifier FROM CryptographicMessageSyntax-2010 -- in [RFC6268] { iso(1) member-body(2) us(840) rsadsi(113549) pkcs(1) pkcs-9(9) smime(16) modules(0) id-mod-cms-2009(58) }
IPAddressOrRange, ASIdOrRange FROM IPAddrAndASCertExtn -- in [RFC3779] { iso(1) identified-organization(3) dod(6) internet(1) security(5) mechanisms(5) pkix(7) mod(0) id-mod-ip-addr-and-as-ident(30) }
ResourceBlock FROM id-mod-rpkiSignedChecklist-2022 -- in [RFC9323] { iso(1) member-body(2) us(840) rsadsi(113549) pkcs(1) pkcs9(9) smime(16) mod(0) id-mod-rpkiSignedChecklist-2022(73) };
ct-rpkiSignedMessage CONTENT-TYPE ::= { TYPE RpkiSignedMessage IDENTIFIED BY id-ct-signedMessage }
id-ct-signedMessage OBJECT IDENTIFIER ::= { iso(1) member-body(2) us(840) rsadsi(113549) pkcs(1) pkcs-9(9) id-smime(16) id-ct(1) signedMessage(TBD) }
RpkiSignedMessage ::= SEQUENCE { version [0] INTEGER DEFAULT 0, purpose OBJECT IDENTIFIER audience OBJECT IDENTIFIER resources ResourceBlock, digestAlgorithm DigestAlgorithmIdentifier, hash Digest } END
